# -*- coding: utf-8 -*-
# 《爱上诗篇》阅读版 v4.3「深入一层」：论证、结构、区分、清单、例证、统计等。本站原创重述与重新组织（非原文），不含页码。
# D[key] = [(标签, 内容), ...]
D = {
'front': [('定位', '推荐语把本书定位为入门书：篇幅不大，却兼顾学术根据与灵修应用。'), ('共同点', '几位推荐者都强调两件事：书中处处把诗篇读向基督；呼吁教会重新在主日唱诗篇。')],
'c1': [('四个理由', '①语言美：真理以诗句表达（如诗23:1、103:2–5、56:8）；②层次深：像矿藏越挖越多；③处境全：不是贺卡式的面面俱到，而是覆盖信徒一切重要的属灵时刻；④满有基督：不只几篇预言诗，整卷都把人引向基督的救赎。'), ('加尔文的评价', '他称诗篇为「灵魂各部分的解剖」，并认为一个人熟悉诗篇的程度，大致反映他对属天教义的掌握。'), ('历史例证', '古教会有「口里常有诗篇，心里常有基督」的说法；法国胡格诺派把诗篇唱本当作在逼迫中的信仰支柱。'), ('结论', '诗篇不是某一宗派的专利，而是整个教会共享的祷告书和诗歌本。')],
'c2': [('为何选诗114', '它是胡格诺派最爱唱的诗之一，也属于逾越节期间吟唱的「出埃及赞美诗」（诗113–118）。'), ('四层读法', '神在列国中的大能 → 神在自然中的大能 → 神的临在（地在主面前震动）→ 神的供应（磐石变水泉）。'), ('细节示范', '海逃跑、约旦倒流、山跳跃分别对应红海、过约旦与西奈；第5–6节以设问重复，突出「无知觉的受造物都有反应，人却常无动于衷」的对照。'), ('身份应用', '胡格诺派与逼迫者同语言，却自认是属灵上「出埃及」的子民；今天的信徒也要分辨自己是在世安家，还是作客旅（彼前2:9–11）。'), ('指向基督', '摩西用同一根杖击打尼罗河、高举在红海、又击打磐石；保罗说那磐石就是基督（林前10:4）。')],
'c3': [('五个难点', '①旧译本（如英文 KJV）退场后，诗歌记忆的传承中断；②教会少用诗篇；③内容复杂；④学术讨论让人望而生畏；⑤整卷看似随意排列。'), ('结构上的困惑', '同一首诗可在赞美、警告、祈求之间转换（如诗95：从敬拜呼召转为警告，人称也由「他」变为「你」）。'), ('出路：默想', '默想就是反复咀嚼：既看词句的形式，也想其中的观念，让经文在心里和口中一再过滤。')],
'c4': [('总表', '大主题：神向义人显出的良善与永不改变的慈爱 → 回应：赞美。从属：①义人仍有罪 → 认罪与哀歌；②恶人亨通 → 嫉妒、求解脱；③义人受苦 → 埋怨、求解脱；④苦中对神与未来的信心 → 求解脱并赞美。'), ('护理的奥秘两种形态', '恶人为何亨通？义人为何受苦？后者更深：痛苦之外，还有「神似乎不在乎」的感受。'), ('历史的功能', '诗人回想神过去的拯救，来支撑对将来的信心——所以诗篇里有大量历史回顾。'), ('示例', '诗25 一首诗里几乎集齐所有主题，可作练习范本。')],
'c5': [('三种人称', '第三人称（诗1:1）、第一人称单数（诗4:1）、第一人称复数（诗44:1）——要问：到底谁在说话？'), ('第一层：大卫', '73 首诗的标题署名大卫；新约也把标题当作可靠（可12:36 引诗110；罗11:9 引诗69），甚至把无标题的诗2、95 归于大卫（徒4:25；来4:7）。'), ('第二层：百姓', '王为自己也为全民说话：最个人的诗仍属全体，最群体的诗仍属个人。'), ('第三层：教会', '教会就是神的以色列（加6:16；弗2:11–22）。据统计新约约有 326 处引用诗篇，出自 115 首——平均每章不止一处。'), ('第四层：基督', '所有诗篇都是大君王耶稣的歌；希伯来书 1–2 章示范了怎样把诗篇读成基督的话。'), ('诗1–2 的门', '诗1 的「这人」原文是单数男性：首先指那位完全守律法的义人；诗2 介绍受膏的王——两首合起来是全卷的引言。')],
'c6': [('形式承载意义', '诗意不只在词句里，也在排列方式里：结构会把重点「指」出来。'), ('中心原则 · 诗23', '「因为你与我同在」位于正中，可以放进每一行之后读；它把前半的牧人画面和后半的筵席主人画面连在一起。'), ('人称分段 · 诗25', '1–7、16–22 节对神说「你」（祷告），8–10、12–15 节讲论「他」（陈述）——代词变化就是分段线索。'), ('其他形式', '平行（同义、对比、递进）、交叉结构、离合诗（按字母次序排列，如诗119 每 8 节同一字母）。')],
'c7': [('组诗与链接', '公认的组诗有哈利路亚诗（146–150）、上行之诗（120–134）等；更多诗靠共同的词语和观念前后相扣，所以要读上下文。'), ('五卷篇幅', '卷一 41 首（第二长）、卷二 31 首、卷三与卷四各 17 首（最短）、卷五 44 首（最长）。'), ('开卷规律', '卷一、卷三都以「一首个人诗 + 一首群体诗」开头；卷二略有变化（42、43 个人，44 群体，而 43 其实是 42 的第三段）。'), ('四个结构观察', '①五卷各以颂赞收尾；②从个人走向群体；③从哀歌走向赞美；④君王主题贯穿全书。'), ('五卷主题', '信心（护理）· 委身（国度）· 危机（应许）· 安慰（信实）· 庆祝（救恩）——作者强调这只是方便记忆的标签，不能涵盖一切。')],
'c8': [('十问', '①值得深究的细节？②属于哪些主题？③人的回应？④个人还是群体？⑤诗歌形式及其意义？⑥中心经文是否即主旨？⑦与所在书卷的关系？⑧前后诗篇的影响？⑨基督怎样是中心？⑩今天怎样对神的百姓说话？'), ('全书编排', '五卷各成一部分、各七章：一章总论（特征、脉络、与他卷的关系），六章精读代表性诗篇。'), ('目标', '不是逐节注释，而是打开一条路：让信徒被诗篇塑造身份，活在诗篇里，也活出诗篇。')],
'b1': [('卷一特征', '直面信徒生活的艰难；比卷二更个人化。41 首中 34 首署名大卫，其中 5 首附有大卫生平背景（诗3、7、18、30、34）。'), ('信心的来源', '①神的应许；②神垂听祷告；③神是避难所；④神终必审判——在逼迫中尤其重要。'), ('19–26 的轨迹', '19 创造与罪 · 20 基督降临 · 21 得胜进入 · 22 受难 · 23 复活 · 24 升天 · 25 五旬节 · 26 最后审判（作者的基督论读法）。')],
'p3': [('背景', '大卫逃避押沙龙（撒下15–18）；示每咒骂时大卫不许报复，反而盼望神因此施恩。'), ('睡眠主题链', '诗3:5 躺下睡觉 → 诗4:8 安然躺下 → 卷一多处呼应；「耶和华扶持我」与诗37:23–24 的「搀扶」同一个词。'), ('咒诅的读法', '先为仇敌归正祷告；对拒不悔改者，审判是公义的结局，伸冤交给神。'), ('基督', '基督今天仍是万王之王、世上君王的元首（启1:5；19:16）。')],
'p8': [('结构', '首尾两句相同的赞美框住全诗；第2节像一个突出的「大屋顶」，打破对称，引出婴孩与仇敌的对照。'), ('中心', '第4–5节「人算什么」位于正中——人也是神创造的中心与巅峰。'), ('荣耀的层次', '神的荣耀高过诸天，因为他是永恒的创造主，荣耀没有界限。'), ('新约', '耶稣引第2节回应圣殿里孩童的颂赞（太21:16）；来2 把「人子」读成基督。')],
'p18': [('结构', '赞美（1–3）→ 神的帮助（4–19）→ 信实的中心（20–29）→ 王的得胜（30–45）→ 赞美（46–50）。'), ('拣选是根基', '「他救拔我，因他喜悦我」（19节）：神的顾念不是因大卫配得。'), ('正直的意义', '大卫并非无罪，而是爱神的律法、为罪忧伤、追求敬虔——这是立约意义上的「完全」。'), ('基督', '耶稣被捕不是软弱，而是甘心顺服父的旨意；外邦人因他赞美神（罗15:9 引49节）。')],
'p21': [('交叉结构', '前半王蒙福 ↔ 后半仇敌受审，首尾以「神的能力」包住全诗（1、13节）。'), ('中心', '第7节「王倚靠耶和华」——我们与神的核心连结就是信靠。'), ('与诗20', '诗20 为出征的王祷告，诗21 为得胜的王感恩，是一对。'), ('提醒', '君王主题虽是卷二重点，在卷一也已出现。')],
'p22': [('最深的苦', '不是仇敌围困（7、12–13节），也不是身体痛苦（14–16节），而是觉得神不听、不在乎。'), ('加尔文的观察', '被神离弃的感受不是基督独有，也不是信徒偶尔才有，而是常见的挣扎；基督的受难独一无二，但这呼求的用法不应只限于他。'), ('赞美的扩展', '苦难的结局是认识神的知识传遍万国，而不是暂时的胜利；神借着话语建立并扩展他的教会。')],
'p30': [('危机的来源', '不是外在敌对，而是顺境中的骄傲：「我凡事平顺，便说我永不动摇」（6节）。'), ('标题与用途', '标题说是献殿之诗；内容个人化，正如诗92 题为安息日之歌而内容并不专讲安息日——关乎用途而非题材。'), ('迫切的祷告', '他的祷告不是形式化的，而是承认需要之大、唯有主能帮助。'), ('末世盼望', '新约的盼望不是灵魂永远在天上，而是身体复活、新天新地；天上的灵魂仍在等候（启6:9–10）。')],
'b2': [('卷二特征', '31 首中 18 首署名大卫（卷一 41 首中 34 首）；焦点从王个人的信心转到王与神国度的关系，更群体化。'), ('交叉结构', '42–44 ↔ 69–72：王与百姓渴慕神的祝福；45–48 ↔ 65–68：在锡安与世界中的王；中心 49–64：王的挣扎与对世界、以色列的警告。'), ('「大卫的祈祷完毕」', '72:20 的说明可能表示卷一、二特别归属大卫，强调王权；其后的大卫诗：卷三 1 首、卷四 2 首、卷五 15 首。')],
'p46': [('背景推测', '希西家年间亚述围城、一夜之间神拯救（王下18–19；赛36–37）。'), ('水的象征', '在干旱的近东，水是生命与丰盛的象征；这条河不是第3节那吞灭人的海，而是温和、供应生命的水源。'), ('卷二主题', '神在地上的国与都城中显出王权与能力。'), ('路德', '《坚固保障》是他对诗46 的意译；他把这首诗读成基督给他子民的应许。')],
'p48': [('四段', '①（1–3）大君王的城美丽坚固；②神挫败列王；③（9–11）默想拯救之神的性情；④（12–14）回到城的主题，传给后代。'), ('中心', '「我们所看见的，正如我们所听见的」（8节）——信心的宣告。'), ('意义的范围', '这不是一座小城的地方史，而关乎地极；唯一存到永远的耶路撒冷是天上的锡安（来12:22；加4:26；启21）。')],
'p51': [('两半', '前半求罪得洁净（赦免），后半求罪人得更新（新心）。'), ('上下文', '诗49–54 彼此相扣，在 52:7 汇合：不以神为力量的人。'), ('忏悔诗分布', '每卷至少一首悔罪诗，唯独卷三没有。'), ('献祭的张力', '中段说神不喜悦祭物，末段（16–19）献祭又成了蒙福的记号：要的是破碎的心，也要锡安被建立后的正当敬拜。')],
'p68': [('三个回应', '①感恩的记念（出埃及、西奈、进迦南）；②喜乐的赞美；③盼望的祷告——国度尚未完全降临，仍求神兴起、驱散仇敌（1节）。'), ('得胜的画面', '统兵的君王逃跑；神的车辇千万；仇敌与附庸带来金银（13节，确切含义不明）。'), ('游行', '24–25 节描绘进入圣所的行列；可能用于抬约柜进城（撒下6），或庆祝胜过哈大底谢（撒下8）。')],
'p69': [('「无故」的意思', '不是没人控告他，而是控告毫无正当理由（4节；约15:25）。'), ('祷告的根据', '神有丰盛的慈爱与慈悲（13、16节），所以诗人敢求「拯救的诚实」。'), ('咒诅的强度', '比诗3 更强烈；主教导先为仇敌归正祷告，本诗也隐约指向这方向；不悔改者的审判与十字架密不可分。'), ('新约引用', '约2:17；约15:25；罗11:9–10；罗15:3；徒1:20；太27:34。')],
'p72': [('给王的礼物', '公平公义（1节）· 长久（5节）· 富足与治权（8–11节）。'), ('给民的福', '王公义，民就安心是非分明（2节）；王富足，民就繁荣（7节）；王顾念困苦人（4、12–13节）。'), ('作者与异象', '所罗门的理想君王图景远远超过以色列的实际经验——只能在基督里成全。')],
'b3': [('卷三特征', '17 首（卷一 41、卷二 31）；只有 1 首署名大卫（86）；73–83 属亚萨，84、85、87、88 属可拉后裔，89 属以探。'), ('危机', '17 首中 14 首带有危机或挣扎的色彩：个人（73）→ 圣殿被毁（74、79）→ 王约似乎失败（89）。'), ('圣殿主题', '圣殿是敬拜与神人相会之所，所以它的毁坏是悲剧的中心。')],
'p73': [('转折点', '进入圣所（17节）：看清恶人的结局。'), ('三个发现', '①神一直与他同在，连怀疑时也是（23节）；②神像父母牵着孩子的手；③神是他的福分直到永远（26节）。'), ('圣所的真实', '祭坛其实满是血与焚烧——那里显明罪的代价，指向基督的祭。'), ('路德', '《坚固保障》末段「财物、性命都可舍，主道依然兴旺」与本诗的结论同调。')],
'p74': [('位置', '描写主前 586 年圣殿被毁，应是最晚编入的诗之一，却放在全书近中心——显示全书的最终编排较晚；卷四、五都在回应这场危机。'), ('敬拜的本质', '敬拜首先不是团契、教导或传福音，更不是娱乐，而是与神相会。'), ('会堂', '「神的会所」可能暗示当时已有会堂，用于读经祷告。'), ('应验', '这祈求最终在基督第一次与第二次降临中得到回答。')],
'p78': [('中心在开头', '与多数诗不同，主旨在引言（1–8节）：要把神的作为传给下一代。'), ('三个试探', '以色列在旷野三次试探神；福音书以耶稣胜过魔鬼的三个试探总结他的顺服。'), ('怒气与恩典', '神给他们大量的肉（27节），怒气也同时临到（31节）；神的忿怒引人悔改（34节）。'), ('留下的问题', '若以色列的忠心系于君王与圣殿，王权衰落、圣殿被毁时怎么办？——这是卷三的核心问题。')],
'p81': [('位置', '不是 150 首的数字中心，却是中间一卷的中心诗。'), ('节期', '第七月：吹角节（月朔）→ 第十日赎罪日 → 十五日起住棚节（利23:23–43）。'), ('核心', '以色列被掳的一切原因可归结为一句：她没有听从她的神；在敬拜这件中心要务上，神特别在意百姓是否听从（参申4）。')],
'p86': [('卷三唯一的大卫诗', '大卫在困苦中，与卷四一样向神的属性寻求安慰。'), ('信心告白的次序', '先宣告神超乎偶像，最后宣告唯有他是神（8–10节）。'), ('连到诗87', '86:9「万民都要来敬拜」在诗87 实现：列国被登记为生在锡安——神造了列国，也要召回列国。')],
'p88': [('诗88', '几乎没有亮光的哀歌，结尾停在黑暗中；但诗人仍称神为「拯救我的神」。'), ('诗89 的转折', '1–37 节对王约的信心之高，使 38 节「你却恼怒你的受膏者」格外刺耳；中心仍是神的应许（26节：你是我的父）。'), ('前后关系', '诗87 的异象（以色列为列国中心）之后，89 的「背约」解释了 88 的深哀。'), ('留给卷四', '王与圣殿失落后怎么办？卷四要回答。')],
'b4': [('五个部分', '90–94 神的伟大；95–100 敬拜的呼召；101–102 神的应许；103–106 赞美与感恩。'), ('两条主线', '创造与摩西之约；唯一未提这两者的是大卫的诗101（王的公义与正直的委身）。'), ('回应卷三', '卷三以「你从前的慈爱在哪里」结束（89:49），卷四以「主啊，你世世代代作我们的居所」开始。')],
'p90': [('开卷', '庄严的祷告，满有信心也满有渴望，回应卷三的危机。'), ('时间', '在神看千年如昨日（4节）；时间对神与对人意义不同。'), ('数算日子', '12节常被当作「人生苦短」的格言，但在全诗里是默想神与他百姓生活的关键。'), ('坚立工作', '信息不是靠自己成功，而是：神既创造并保守了立约的百姓，也必祝福我们手所作的工。')],
'p92': [('安息日的目的', '安息日从起初就不是目的本身，而是达成目的（敬拜与安息于神）的途径（利23:1–3）。'), ('为人设立', '耶稣说安息日是为「人」设立的（可2:27），属于全人类。'), ('主日', '耶稣是安息日的主；他的复活赢得了安息，所以基督徒以在他里面安息与敬拜开始每一周。')],
'p95': [('位置', '开启卷四第二部分：在敬拜中得安慰。'), ('身体的敬拜', '歌唱、欢呼、跪拜；诗篇中被呼召拍手的只有列国与江河（47:1；98:8），以色列在约阿施登基时拍手（王下11:12）。'), ('祷告姿势', '保罗也提到屈膝和举手（弗3:14；提前2:8）。'), ('米利巴的教训', '危机中可以向神倾心吐意，但不可试探神。')],
'p103': [('位置', '卷四末四首的第一首，焦点是在赞美中得安慰；卷四第二首大卫诗。'), ('中心 7–18 节', '圣经中默想神圣约之爱最伟大的经文之一；改革宗教会常在圣餐礼拜中使用——主的桌有形地、本诗有声地宣告同一恩典。'), ('不是纵容的爱', '神的慈爱不等于对罪无所谓；恩典不让人安然享受罪中之乐。'), ('对比', '与只会模糊重复「他行了大事」的现代诗歌相比，本诗具体数算恩惠。')],
'p104': [('对应创1', '先赞美神的威严，再依次展开光、天、水、地、生物、时序。'), ('第五点', '神不是造完就放手的设计者，而是一直在护理与参与。'), ('旧歌与新歌', '启4 长老为创造唱颂歌，启5 为救赎向羔羊唱「新歌」。'), ('复原', '这更新由基督第一次降临开启，在他再来时完成（弗1:9–10）。')],
'p106': [('三段', '①（1–12）赞美与祷告，求神记念我；②（13–33）旷野六宗罪，每段都以「忘记」为根；③（34–48）迦南与被掳。'), ('对比', '神的拯救 ↔ 以色列的健忘与不忠；但过去的拯救成了将来拯救的盼望。'), ('卷四收尾', '无论创造与圣约中有多少安慰，完全的得救仍在将来（47节：从外邦中招聚我们）。')],
'b5': [('篇幅', '最长的一卷（44 首），紧接两卷短卷（各 17 首）。'), ('重新肯定王', '若卷三的焦点是王族衰落带来的危机，卷五就重新肯定君王与神给王的祝福。'), ('诗119', '离合诗：每段 8 节以同一个希伯来字母开头，共 22 段。'), ('收尾', '146–150 的赞美组诗完成全卷的欢庆。')],
'p109': [('接续', '卷五的赞美回应 106:47 求招聚的祷告；107:1 的话也曾在约柜入城与献殿时使用（代上16:8；代下5:13；7:3）。'), ('咒诅的解读', '6–19 节可能是仇敌咒诅王的话；但新约把第8节用在犹大身上（徒1:20），又引第25节描写十字架下的讥诮（太27:39）。'), ('基督', '基督被无故恨恶、被出卖，却为钉他的人祷告。')],
'p110': [('两个「主」', '第一个是立约之名「耶和华」，第二个是大卫称为「我主」的那位；耶稣以此问倒法利赛人（太22:41–46）。'), ('升华王权', '卷五第三首大卫诗，把王权提升到祭司层面：照麦基洗德的等次（来5–7）。'), ('祭司的工作', '代求、洁净（参路5:14）——基督兼有王与祭司两职。')],
'p118': [('历史用途', '首尾的称谢原用于约柜安抵耶路撒冷；最后的晚餐后耶稣与门徒同唱的诗很可能包括本诗。'), ('房角石', '恶园户的比喻后，耶稣引 22–23 节指自己（太21:42）；使徒也一再引用（徒4:11；彼前2:7）。'), ('路德的座右铭', '17节：我必不致死，仍要存活，并要传扬耶和华的作为。'), ('出埃及赞美诗', '113–118 不只适用于出埃及，也适用于以色列历史中多次的拯救（如113:7）。')],
'p121': [('上行之诗', '第一首（120）表达远离神、渴慕平安；最后一首（134）讲论从锡安临到百姓的祝福。'), ('具体的语言', '诗人不说抽象的「我想到困境」，而是「我要向山举目」；危险具体到日晒、月害，最后总括为一切灾害（7节）。'), ('敬拜中的用途', '古教会与加尔文复兴的礼拜，都以「我们的帮助在乎耶和华的名」开始敬拜。')],
'p135': [('三大主题', '神的良善（拣选雅各）· 神的伟大（超乎万神，5节）· 偶像的虚空。'), ('诗篇很好懂', '作者统计：82 首没有人名地名；31 首只用最熟悉的五个名（锡安、以色列、耶路撒冷、雅各、大卫）；另 13 首再用 15 个较熟悉的名称；真正较晦涩的大约只有 5 首（60、83、120、135、136）——约 145 首对基督徒都很易懂。')],
'p138': [('位置', '开启卷五第六组（138–145，八首大卫诗），回应卷三的危机与诗137「怎能在外邦唱歌」（4节）的问题。'), ('王权复原', '这组诗讲王权的更新：受苦的王被神保守性命，成了赐生命者。'), ('暴力的现实', '圣经中战争的残酷是真实的（如王下8:12）；诗137 的呼声要放在这一背景下理解。')],
'c44': [('共同记号', '五首都以「哈利路亚」开始也结束。'), ('与开头对称', '诗1–2 是无标题的引言，其后接大卫诗；146–150 也是无标题的结尾，前面是大卫诗——前后呼应。'), ('对应论证', '内容、语言与主题都支持：146 对卷一、147 对卷二、148 对卷三、149 对卷四、150 对卷五。')],
'p146': [('结构', '中心「守诚实直到永远」（6节）两旁：创造（6节）与供应（7节）；外圈：不要倚靠君王（3–4节）↔ 耶和华永远作王（10节）。'), ('与卷一的连结', '146:8 的义人对应诗1:5；146:9 的「恶人的道路」对应诗1:6。')],
'p147': [('与卷二的连结', '国度、锡安与「困苦人」：诗72:4、12–13 的王顾念穷乏；诗42–43 反复的「需要」；诗72:16 山顶五谷茂盛。'), ('神的话', '最独特的供应是他把律例典章赐给雅各（19–20节）。')],
'p148': [('与卷三的连结', '看似只是创造之歌，其实对应诗89：天是神信实的象征（89:2、5）；148:14「为百姓高举角」回应王约的危机。'), ('结尾之争', '14节结尾太突然，有学者认为应属诗149 的第一节。'), ('启示录', '耶稣是「从死里首先复活、世上君王的元首」（启1:5）——诗89 的大卫王族在他身上复兴。')],
'p149': [('与卷四的连结', '回应 106:48 的颂赞；卷四的圣约信实在恩典之约的赞美中完成。'), ('跳舞', '圣经记载以色列在正式敬拜中跳舞只有一次，而且是在金牛犊面前（出32:19）；跳舞通常是庆祝胜利等生活场合的喜乐（出15:20；撒上18:6）。'), ('两刃的刀', '今天不是有形的战争，而是以圣灵和神的道服侍神，确信神在基督里成就他的旨意；149:9 是诗1:5 的应用。')],
'p150': [('四问', '在哪里（圣所与穹苍）· 为什么（大能作为与极美大德，2节）· 怎样（各样乐器）· 谁（凡有气息的）。'), ('与卷五的连结', '107:22「欢呼述说他的作为」、145:11「传说你国的荣耀」——卷五不断呼召赞美，150 是完全的赞美。')],
'post': [('三种方法', '个人读与默想 · 听讲道 · 唱诗篇。'), ('为什么唱诗篇', '①历代教师（奥古斯丁、路德、加尔文、诺克斯、凯波尔、约翰·慕理等）都敦促；②诗篇出于神的默示，内容与形式都蒙神悦纳；③它完美平衡关于神的客观真理与人对神的主观回应。'), ('近况', '近年多个改革宗与长老会宗派出版或筹备新的诗篇歌本。')],
'bio': [('经历', '曾任教于哥顿康威尔神学院、斯坦福大学与费城威斯敏斯特神学院；加州威斯敏斯特神学院第三任院长；北美联合改革宗教会牧师。'), ('著作方向', '以加尔文与宗教改革史为主，另有诗篇与教会论著作；2010 年有纪念文集《持守改革宗信仰》。')],
}
